\caption[The external memory model]{In the external memory model,
  accessing an individual item, \ensuremath{\ensuremath{\ensuremath{\mathit{x}}}}, in the external memory requires
  reading the entire block containing \ensuremath{\ensuremath{\ensuremath{\mathit{x}}}} into RAM.}
  \figlabel{em}

\begin{enumerate}
  \item \ensuremath{\ensuremath{\mathrm{read\_block}(\ensuremath{\mathit{i}})}}: Return the contents of the block whose index is \ensuremath{\ensuremath{\ensuremath{\mathit{i}}}}.
  \item \ensuremath{\ensuremath{\mathrm{write\_block}(\ensuremath{\mathit{i}},\ensuremath{\mathit{b}})}}: Write contents of \ensuremath{\ensuremath{\ensuremath{\mathit{b}}}} to the block whose
    index is \ensuremath{\ensuremath{\ensuremath{\mathit{i}}}}.
  \item \ensuremath{\ensuremath{\mathrm{place\_block}(\ensuremath{\mathit{b}})}}: Return a new index and store the contents of \ensuremath{\ensuremath{\ensuremath{\mathit{b}}}}
    at this index.
  \item \ensuremath{\ensuremath{\mathrm{free\_block}(\ensuremath{\mathit{i}})}}: Free the block whose index is \ensuremath{\ensuremath{\ensuremath{\mathit{i}}}}.  This indicates
    that the contents of this block are no longer used so the external
    memory allocated by this block may be reused.
\end{enumerate}

