\begin{description}
  \item[Borrowing:]
  \index{borrow}%
  If \ensuremath{\ensuremath{\ensuremath{\mathit{w}}}} has a sibling, \ensuremath{\ensuremath{\ensuremath{\mathit{v}}}}, with more than $B-1$ keys,
  then \ensuremath{\ensuremath{\ensuremath{\mathit{w}}}} can borrow some keys (and possibly also children) from \ensuremath{\ensuremath{\ensuremath{\mathit{v}}}}.
  More specifically, if \ensuremath{\ensuremath{\ensuremath{\mathit{v}}}} stores \ensuremath{\ensuremath{\mathrm{size}(\ensuremath{\mathit{v}})}} keys, then between them,
  \ensuremath{\ensuremath{\ensuremath{\mathit{v}}}} and \ensuremath{\ensuremath{\ensuremath{\mathit{w}}}} have a total of
  \[
     B-2 + \ensuremath{\ensuremath{\mathrm{size}(\ensuremath{\mathit{w}})}} \ge 2B-2
  \]
  keys.  We can therefore shift keys from \ensuremath{\ensuremath{\ensuremath{\mathit{v}}}} to \ensuremath{\ensuremath{\ensuremath{\mathit{w}}}} so that each of
  \ensuremath{\ensuremath{\ensuremath{\mathit{v}}}} and \ensuremath{\ensuremath{\ensuremath{\mathit{w}}}} has at least $B-1$ keys.  This process is illustrated in
  \figref{btree-borrow}.
  \begin{figure}
      \centering{\begin{tabular}{@{}l@{}}
       \includegraphics[width=\ScaleIfNeeded]{figs-python/btree-borrow-1} \\[2ex]
       \multicolumn{1}{c}{\ensuremath{\ensuremath{\mathrm{shift\_rL}(\ensuremath{\mathit{v}},\ensuremath{\mathit{w}})}}} \\ 
       \multicolumn{1}{c}{$\Downarrow$} \\[2ex]
       \includegraphics[width=\ScaleIfNeeded]{figs-python/btree-borrow-2} \\
     \end{tabular}}
    \caption[Borrowing in a $B$-tree]{If \ensuremath{\ensuremath{\ensuremath{\mathit{v}}}} has more than $B-1$ keys,
       then \ensuremath{\ensuremath{\ensuremath{\mathit{w}}}} can borrow keys from \ensuremath{\ensuremath{\ensuremath{\mathit{v}}}}.}
    \figlabel{btree-borrow}
  \end{figure}

  \item[Merging:]
  \index{merge}%
  If \ensuremath{\ensuremath{\ensuremath{\mathit{v}}}} has only $B-1$ keys, we must do something more
  drastic, since \ensuremath{\ensuremath{\ensuremath{\mathit{v}}}} cannot afford to give any keys to \ensuremath{\ensuremath{\ensuremath{\mathit{w}}}}.  Therefore,
  we \emph{merge} \ensuremath{\ensuremath{\ensuremath{\mathit{v}}}} and \ensuremath{\ensuremath{\ensuremath{\mathit{w}}}} as shown in \figref{btree-merge}.  The merge
  operation is the opposite of the split operation.  It takes two nodes
  that contain a total of $2B-3$ keys and merges them into a single
  node that contains $2B-2$ keys.  (The additional key comes from the
  fact that, when we merge \ensuremath{\ensuremath{\ensuremath{\mathit{v}}}} and \ensuremath{\ensuremath{\ensuremath{\mathit{w}}}}, their common parent, \ensuremath{\ensuremath{\ensuremath{\mathit{u}}}}, now
  has one less child and therefore needs to give up one of its keys.)

  \begin{figure}
     \centering{\begin{tabular}{@{}l@{}}
       \includegraphics[width=\ScaleIfNeeded]{figs-python/btree-merge-1} \\[2ex]
       \multicolumn{1}{c}{\ensuremath{\ensuremath{\mathrm{merge}(\ensuremath{\mathit{v}},\ensuremath{\mathit{w}})}}} \\ 
       \multicolumn{1}{c}{$\Downarrow$} \\[2ex]
       \includegraphics[width=\ScaleIfNeeded]{figs-python/btree-merge-2} \\
     \end{tabular}}
     \caption[Merging in a $B$-tree]{Merging two siblings \ensuremath{\ensuremath{\ensuremath{\mathit{v}}}} and \ensuremath{\ensuremath{\ensuremath{\mathit{w}}}}
     in a $B$-tree ($B=3$).}
     \figlabel{btree-merge}
  \end{figure}
\end{description}
