\begin{enumerate}
  \item In the external memory model, the running time of \ensuremath{\ensuremath{\mathrm{find}(\ensuremath{\mathit{x}})}},
    \ensuremath{\ensuremath{\mathrm{add}(\ensuremath{\mathit{x}})}}, and \ensuremath{\ensuremath{\mathrm{remove}(\ensuremath{\mathit{x}})}} in a $B$-tree is $O(\log_B \ensuremath{\ensuremath{\ensuremath{\mathit{n}}}})$.
  \item In the word-RAM model, the running time of \ensuremath{\ensuremath{\mathrm{find}(\ensuremath{\mathit{x}})}} is $O(\log \ensuremath{\ensuremath{\ensuremath{\mathit{n}}}})$
    and the running time of \ensuremath{\ensuremath{\mathrm{add}(\ensuremath{\mathit{x}})}} and \ensuremath{\ensuremath{\mathrm{remove}(\ensuremath{\mathit{x}})}} is $O(B\log \ensuremath{\ensuremath{\ensuremath{\mathit{n}}}})$.
\end{enumerate}

\begin{lem}\lemlabel{btree-split}
  Starting with an empty $B$-tree and performing any sequence of
  $m$ \ensuremath{\ensuremath{\mathrm{add}(\ensuremath{\mathit{x}})}} and \ensuremath{\ensuremath{\mathrm{remove}(\ensuremath{\mathit{x}})}} operations results in at most $3m/2$ splits,
  merges, and borrows being performed.
\end{lem}

\begin{thm}[External Memory $B$-Trees]
  A BTree implements the SSet interface. In the external memory model,
  a BTree supports the operations \ensuremath{\ensuremath{\mathrm{add}(\ensuremath{\mathit{x}})}}, \ensuremath{\ensuremath{\mathrm{remove}(\ensuremath{\mathit{x}})}}, and \ensuremath{\ensuremath{\mathrm{find}(\ensuremath{\mathit{x}})}}
  in $O(\log_B \ensuremath{\ensuremath{\ensuremath{\mathit{n}}}})$ time per operation.
\end{thm}

